/* ============================================
   ACCURANT - SYSTEMEMBLEMS.JS
   Lambang tiga sistem kekuatan (kanvas 1:1, 256x256):
     Artifact -> lambang rune logam    (EMBLEM_IMG.artifact)
     Mutation -> lambang sigil merah   (EMBLEM_IMG.mutation)
     Confer   -> lambang sayap emas    (EMBLEM_IMG.confer)
   Dimuat SETELAH charactersExtra.js. Berkas ini sendiri yang memasang gambar ke
   semua karakter sesuai sistem kekuatannya, jadi tidak bergantung pada versi
   emblems.js / charactersExtra.js yang kamu pakai.
   Kalau gambar gagal dimuat, setPortrait (characters.js) memakai ikon vektor
   dari systemEmblemSvg() di bawah, jadi profil tidak pernah kosong.
   ============================================ */

(function () {
  "use strict";
  var IMG = {
    artifact: "data:image/jpeg;base64,",
    mutation: "data:image/jpeg;base64,",
    confer: "data:image/jpeg;base64,"
  };
  if (typeof EMBLEM_IMG === "object") {
    EMBLEM_IMG.artifact = IMG.artifact;
    EMBLEM_IMG.mutation = IMG.mutation;
    EMBLEM_IMG.confer = IMG.confer;
  }
  var BY_SYSTEM = { Artifact: IMG.artifact, Mutation: IMG.mutation, Confer: IMG.confer };
  if (typeof CHARACTER_DATABASE !== "undefined") {
    CHARACTER_DATABASE.forEach(function (c) {
      if (BY_SYSTEM[c.powerSystem]) c.image = BY_SYSTEM[c.powerSystem];
    });
  }
})();

/** Ikon vektor cadangan per sistem kekuatan (dipakai kalau gambar gagal dimuat). */
function systemEmblemSvg(system) {
  var o = '<svg viewBox="0 0 64 64" width="100%" height="100%" aria-hidden="true">';
  if (system === "Artifact") {
    return o + '<circle cx="32" cy="32" r="26" fill="#0b0c0f" stroke="#b8a074" stroke-width="2.5"/>' +
      '<circle cx="32" cy="32" r="19" fill="none" stroke="#8f8468" stroke-width="1.5" stroke-dasharray="3 3"/>' +
      '<path d="M32 15 47 41H17Z" fill="none" stroke="#e8d3a0" stroke-width="2.2" stroke-linejoin="round"/>' +
      '<circle cx="32" cy="34" r="4.5" fill="#e8d3a0"/></svg>';
  }
  if (system === "Mutation") {
    return o + '<circle cx="32" cy="32" r="26" fill="#12040a" stroke="#ff3b3b" stroke-width="2.5"/>' +
      '<path d="M32 10 54 48H10Z" fill="none" stroke="#ff5a5a" stroke-width="1.8" stroke-linejoin="round"/>' +
      '<circle cx="32" cy="34" r="8" fill="#12040a" stroke="#ff3b3b" stroke-width="2"/>' +
      '<circle cx="32" cy="34" r="2.5" fill="#ff3b3b"/><path d="M32 42v14" stroke="#b01020" stroke-width="3" stroke-linecap="round"/></svg>';
  }
  if (system === "Confer") {
    return o + '<circle cx="32" cy="32" r="26" fill="#0a0f1e" stroke="#c9d6ff" stroke-width="2"/>' +
      '<path d="M32 40C26 34 18 31 8 33c4 7 12 11 24 11Zm0 0c6-6 14-9 24-7-4 7-12 11-24 11Z" fill="#f3c969" fill-opacity=".85"/>' +
      '<path d="M32 16l7 10-7 10-7-10Z" fill="#fff6d6" stroke="#f3c969" stroke-width="1.6" stroke-linejoin="round"/></svg>';
  }
  return "";
}